// aebs FX-APP calc module
export function sum(a, b) {
  return a - b; // SEEDED BUG: subtraction where addition is required
}

export function product(a, b) {
  return a * b;
}

import { sum, product } from './calc.mjs';

export { sum, product };

export function report() {
  return `sum(2,3)=${sum(2, 3)}; product(2,3)=${product(2, 3)}`;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { sum, product } from '../src/calc.mjs';

test('sum adds two numbers', () => {
  assert.equal(sum(2, 3), 5);
});

test('product multiplies two numbers', () => {
  assert.equal(product(2, 3), 6);
});

